'use client';

import { useEffect, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pendingApprovalsOf,
  type RunSnapshot,
} from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { Board } from './board';
import { Budget } from './budget';
import { DECLINED_LINE, POSTED_LINE } from './data';
import { Fleet } from './fleet';
import { Graph } from './graph';
import { Monitor } from './monitor';
import { PageHeader, SlimBar, useCondensedHeader } from './page-header';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type Decision,
  type ScrollTarget,
} from './session';
import { Waterfall } from './waterfall';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The slim bar covers the top of the page once it has condensed: a panel brought into view stops below it. */
const SCROLL_MARGIN_PX = 64;

/**
 * One column under 48rem, two from there, three from 64rem. The grid names the places of the panels,
 * so their order in the page stays the order a phone reads them in.
 */
const PANELS =
  "grid grid-cols-1 gap-4 @3xl:grid-cols-2 @3xl:[grid-template-areas:'monitor_budget'_'graph_graph'_'fleet_fleet'_'waterfall_waterfall'_'board_board'] @5xl:grid-cols-3 @5xl:[grid-template-areas:'monitor_graph_graph'_'budget_waterfall_waterfall'_'fleet_board_board']";

function scrollTopOf(scroller: HTMLElement, target: ScrollTarget) {
  if (target === 'top') {
    return 0;
  }
  const panel = scroller.querySelector<HTMLElement>('[data-panel="fleet"]');
  if (!panel) {
    return 0;
  }
  const panelTop = panel.getBoundingClientRect().top;
  const scrollerTop = scroller.getBoundingClientRect().top;
  const offset = panelTop - scrollerTop + scroller.scrollTop;
  return Math.max(0, offset - SCROLL_MARGIN_PX);
}

function scrollBehaviorOf(shouldReduceMotion: boolean): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function announcementOf(run: RunSnapshot) {
  const pending = pendingApprovalsOf(run)[0];
  if (pending) {
    return `${pending.title}. Allow or deny it`;
  }
  if (run.status === 'done') {
    return `The run is done. ${POSTED_LINE}`;
  }
  if (run.status === 'cancelled') {
    return DECLINED_LINE;
  }
  return '';
}

/** Nothing calls a network. A real backend plugs in here: the answer of a person to the request that waits on them. */
export type Application07Props = {
  onApprove?: () => void;
  onDeny?: () => void;
};

export default function Application07({
  onApprove,
  onDeny,
}: Application07Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const { sentinelRef, isCondensed } = useCondensedHeader(scrollerRef);
  const shouldReduceMotion = usePrefersReducedMotion();
  const { run, focusAgentId, scrollTarget } = state;
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, announcementOf(run));

  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!scroller) {
      return;
    }
    const top = scrollTopOf(scroller, scrollTarget);
    const behavior = scrollBehaviorOf(shouldReduceMotion);
    scroller.scrollTo({ top, behavior });
  }, [scrollTarget, shouldReduceMotion]);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** The two buttons leave with the request, so the focus goes to what replaces them: the line that says what was decided. */
  function decide(decision: Decision) {
    act({ type: 'decided', decision });
    focusLater('[data-request]');
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    onApprove?.();
  }

  function pickAgent(id: string) {
    if (focusAgentId === id) {
      act({ type: 'focused', id: null });
      return;
    }
    act({ type: 'focused', id });
  }

  function review() {
    focusLater('[data-approval]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='relative h-dvh min-h-[40rem] overflow-hidden'>
          <div
            ref={scrollerRef}
            onWheel={takeOver}
            className='relative h-full overflow-y-auto'
          >
            <SlimBar
              run={run}
              isCondensed={isCondensed}
              canReplay={canReplay}
              onReplay={restart}
            />
            <div className='mx-auto flex w-full max-w-[90rem] flex-col gap-5 px-3 pb-8 @xl:px-5'>
              <PageHeader
                run={run}
                sentinelRef={sentinelRef}
                canReplay={canReplay}
                onReplay={restart}
              />
              <div className={PANELS}>
                <Monitor
                  run={run}
                  focusAgentId={focusAgentId}
                  pressed={pressed}
                  onDecide={decide}
                  className='@3xl:[grid-area:monitor]'
                />
                <Budget
                  run={run}
                  focusAgentId={focusAgentId}
                  className='@3xl:[grid-area:budget]'
                />
                <Graph
                  run={run}
                  focusAgentId={focusAgentId}
                  onFocusAgent={pickAgent}
                  className='@3xl:[grid-area:graph]'
                />
                <Fleet
                  run={run}
                  focusAgentId={focusAgentId}
                  pressed={pressed}
                  onFocusAgent={pickAgent}
                  className='@3xl:[grid-area:fleet]'
                />
                <Waterfall
                  run={run}
                  focusAgentId={focusAgentId}
                  className='@3xl:[grid-area:waterfall]'
                />
                <Board
                  run={run}
                  focusAgentId={focusAgentId}
                  onReview={review}
                  className='@3xl:[grid-area:board]'
                />
              </div>
            </div>
          </div>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import {
  seriesColorOf,
  type AgentStatus,
  type RunAgent,
} from '@/registry/ndeko/lib/agent-run';
import { BookIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { MeshTile, type MeshTileSize } from '@/registry/ndeko/ui/mesh-tile';

import { toolMetaOf } from './data';

export const AGENT_STATUS_WORD: Record<AgentStatus, string> = {
  idle: 'Idle',
  running: 'Running',
  waiting: 'Waiting on you',
  failed: 'Failed',
  done: 'Done',
};

export const AGENT_STATUS_WORDS = Object.values(AGENT_STATUS_WORD);

const DOT_TONE: Record<AgentStatus, string> = {
  idle: 'bg-muted-foreground/45',
  running: 'bg-info',
  waiting: 'bg-warning',
  failed: 'bg-destructive',
  done: 'bg-success',
};

type StatusDotProps = {
  status: AgentStatus;
  isPulsing?: boolean;
  className?: string;
};

/** A dot only breathes while its agent really runs, and the page lets a few of them do it at a time. */
export function StatusDot({
  status,
  isPulsing = false,
  className,
}: StatusDotProps) {
  const isLive = status === 'running' && isPulsing;

  return (
    <span
      aria-hidden='true'
      className={cn(
        'size-1.5 shrink-0 rounded-full transition-colors duration-200',
        DOT_TONE[status],
        isLive && 'animate-pulse',
        className
      )}
    />
  );
}

type AgentTileProps = {
  agent: Pick<RunAgent, 'name' | 'series'>;
  size?: MeshTileSize;
  className?: string;
};

export function AgentTile({ agent, size = 'lg', className }: AgentTileProps) {
  const color = seriesColorOf(agent.series);

  return (
    <MeshTile
      seed={agent.name}
      color={color}
      size={size}
      className={className}
    />
  );
}

type ToolTileProps = {
  toolId: string;
  className?: string;
};

/** A known tool wears its real mark. The ledger has none, so it wears a key cap with a book. */
export function ToolTile({ toolId, className }: ToolTileProps) {
  const tool = toolMetaOf(toolId);
  if (tool.brand) {
    return (
      <BrandTile
        brand={tool.brand}
        size='lg'
        title={tool.name}
        className={className}
      />
    );
  }

  return (
    <span
      title={tool.name}
      className={cn(
        'keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md',
        className
      )}
    >
      <BookIcon className='size-3.5' />
      <span className='sr-only'>{tool.name}</span>
    </span>
  );
}

const SMALL_COST: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 3,
  maximumFractionDigits: 3,
};

const LARGE_COST: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

/** Matches `formatCost`: three decimals under a dollar, two above. */
function costFormatOf(usd: number) {
  if (usd < 1) {
    return SMALL_COST;
  }
  return LARGE_COST;
}

type CostFigureProps = {
  usd: number;
  className?: string;
};

export function CostFigure({ usd, className }: CostFigureProps) {
  return (
    <MotionNumber
      value={usd}
      format={costFormatOf(usd)}
      className={cn('tabular-nums', className)}
    />
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import {
  pendingApprovalsOf,
  type ApprovalRequest,
  type RunSnapshot,
} from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CircleXIcon } from '@/registry/ndeko/lib/icons';
import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Badge, type BadgeProps } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { Spinner } from '@/registry/ndeko/ui/spinner';

import { DECLINED_LINE, POSTED_LINE } from './data';
import type { Decision } from './session';

export type ApprovalView = 'none' | 'asking' | 'posting' | 'posted' | 'denied';

export function approvalViewOf(run: RunSnapshot): ApprovalView {
  const approval = run.approvals[0];
  if (!approval) {
    return 'none';
  }
  if (approval.status === 'pending') {
    return 'asking';
  }
  if (approval.status === 'denied') {
    return 'denied';
  }
  const call = run.calls.find((candidate) => candidate.id === 'c7');
  if (call?.status === 'done') {
    return 'posted';
  }
  return 'posting';
}

const RISK_WORD: Record<ApprovalRequest['risk'], string> = {
  low: 'Low risk',
  medium: 'Medium risk',
  high: 'High risk',
};

const RISK_VARIANT: Record<ApprovalRequest['risk'], BadgeProps['variant']> = {
  low: 'success',
  medium: 'warning',
  high: 'destructive',
};

type RequestBodyProps = {
  approval: ApprovalRequest;
  pressed: string | null;
  onDecide: (decision: Decision) => void;
};

function RequestBody({ approval, pressed, onDecide }: RequestBodyProps) {
  const titleId = useId();
  const keysId = useId();

  function allow() {
    onDecide('approved');
  }

  function deny() {
    onDecide('denied');
  }

  function decideFromKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      deny();
      return;
    }
    const isOnCard = event.target === event.currentTarget;
    const isEnter = event.key === 'Enter';
    if (isEnter && isOnCard) {
      event.preventDefault();
      allow();
    }
  }

  return (
    <div
      role='group'
      tabIndex={0}
      data-approval
      aria-labelledby={titleId}
      aria-describedby={keysId}
      onKeyDown={decideFromKeys}
      className='focus-visible:ring-ring/25 flex flex-col gap-3 rounded-xl p-3 outline-none focus-visible:ring-[3px] focus-visible:ring-inset'
    >
      <div className='flex items-start gap-2'>
        <h3 id={titleId} className='min-w-0 flex-1 text-[13px] font-medium'>
          {approval.title}
        </h3>
        <Badge variant={RISK_VARIANT[approval.risk]}>
          {RISK_WORD[approval.risk]}
        </Badge>
      </div>
      <p className='text-muted-foreground text-xs leading-5'>
        {approval.detail}
      </p>
      <pre className='bg-foreground/[0.04] overflow-x-auto rounded-lg p-2.5 font-mono text-xs leading-relaxed whitespace-pre-wrap'>
        {approval.command}
      </pre>
      <div className='flex flex-wrap items-center gap-2'>
        <Button
          type='button'
          size='sm'
          onClick={allow}
          className={pressedSolidOf(pressed === 'allow')}
        >
          Allow
          <Kbd className='ms-0.5'>Enter</Kbd>
        </Button>
        <Button type='button' size='sm' variant='outline' onClick={deny}>
          Deny
          <Kbd className='ms-0.5'>Esc</Kbd>
        </Button>
        <Badge variant='secondary' className='ms-auto'>
          Illustrative
        </Badge>
        <span id={keysId} className='sr-only'>
          Enter allows, Escape denies
        </span>
      </div>
    </div>
  );
}

function ResultGlyph({ view }: { view: ApprovalView }) {
  if (view === 'posting') {
    return <Spinner aria-hidden='true' />;
  }
  if (view === 'denied') {
    return <CircleXIcon className='text-muted-foreground size-4 shrink-0' />;
  }
  return <DrawnCheck tone='success' entrance='draw' />;
}

function resultLineOf(view: ApprovalView) {
  if (view === 'posting') {
    return 'Posting the entries';
  }
  if (view === 'denied') {
    return DECLINED_LINE;
  }
  return POSTED_LINE;
}

function ResultLine({ view }: { view: ApprovalView }) {
  return (
    <div className='flex min-h-11 items-start gap-2.5 p-3 text-[13px] leading-5'>
      <Swap swapKey={view} className='mt-px'>
        <ResultGlyph view={view} />
      </Swap>
      <p
        key={view}
        className='min-w-0 transition-opacity duration-300 starting:opacity-0'
      >
        {resultLineOf(view)}
      </p>
    </div>
  );
}

function viewKeyOf(isAsking: boolean) {
  if (isAsking) {
    return 'request';
  }
  return 'result';
}

type ApprovalBlockProps = {
  run: RunSnapshot;
  pressed: string | null;
  onDecide: (decision: Decision) => void;
};

export function ApprovalBlock({ run, pressed, onDecide }: ApprovalBlockProps) {
  const fade = fadePresence();
  const view = approvalViewOf(run);
  const pending = pendingApprovalsOf(run)[0];
  const approval = pending ?? run.approvals[0];
  if (!approval || view === 'none') {
    return null;
  }
  const isAsking = view === 'asking';

  return (
    <section
      data-request
      tabIndex={-1}
      aria-label='Request waiting for an answer'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-300 outline-none starting:opacity-0'
    >
      <AnimatedSize>
        <AnimatePresence initial={false} mode='popLayout'>
          <motion.div key={viewKeyOf(isAsking)} {...fade}>
            {isAsking && (
              <RequestBody
                approval={approval}
                pressed={pressed}
                onDecide={onDecide}
              />
            )}
            {!isAsking && <ResultLine view={view} />}
          </motion.div>
        </AnimatePresence>
      </AnimatedSize>
    </section>
  );
}

'use client';

import { LayoutGroup, motion, type Transition } from 'motion/react';
import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  elapsedOf,
  formatDuration,
  type PlanStep,
  type RunSnapshot,
} from '@/registry/ndeko/lib/agent-run';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { AgentTile } from './agent-parts';
import {
  agentOf,
  boardOf,
  placementOf,
  type BoardTask,
  type LaneId,
} from './model';
import { Panel } from './panel';

type Lane = {
  id: LaneId;
  label: string;
  emptyLine: string;
};

const LANES: Lane[] = [
  { id: 'queued', label: 'Queued', emptyLine: 'Nothing waits' },
  { id: 'running', label: 'Running', emptyLine: 'Nothing runs' },
  { id: 'needs', label: 'Needs you', emptyLine: 'Nothing needs you' },
  { id: 'done', label: 'Done', emptyLine: 'Nothing is done yet' },
];

function dimOf(isDimmed: boolean) {
  if (isDimmed) {
    return 'opacity-40';
  }
  return undefined;
}

function stepOf(run: RunSnapshot, task: BoardTask): PlanStep | undefined {
  return run.plan.find((step) => step.id === task.id);
}

function TaskClock({
  step,
  lane,
}: {
  step: PlanStep | undefined;
  lane: LaneId;
}) {
  if (!step) {
    return null;
  }
  if (lane === 'running') {
    return (
      <LiveDuration
        item={step}
        isRunning
        className='text-muted-foreground text-xs'
      />
    );
  }
  if (lane === 'done') {
    const elapsed = elapsedOf(step, step.endedAt ?? 0);
    return (
      <span className='text-muted-foreground text-xs tabular-nums'>
        {formatDuration(elapsed)}
      </span>
    );
  }
  return null;
}

type TaskCardProps = {
  run: RunSnapshot;
  task: BoardTask;
  placement: string;
  travel: Transition;
  isDimmed: boolean;
  onReview: () => void;
};

function TaskCard({
  run,
  task,
  placement,
  travel,
  isDimmed,
  onReview,
}: TaskCardProps) {
  const owner = agentOf(run, task.ownerId);
  const step = stepOf(run, task);
  const isSkipped = task.status === 'skipped';

  return (
    <motion.li
      layout='position'
      layoutId={task.id}
      layoutDependency={placement}
      transition={{ layout: travel }}
    >
      <div
        className={cn(
          'bg-card hairline-ring ring-border dark:bg-foreground/[0.06] flex flex-col gap-2 rounded-lg p-2.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-200',
          dimOf(isDimmed)
        )}
      >
        <p
          className={cn(
            'text-[13px] leading-snug font-medium',
            isSkipped && 'text-muted-foreground line-through'
          )}
        >
          {task.title}
        </p>
        <div className='flex items-center gap-2 text-xs'>
          {owner && <AgentTile agent={owner} size='sm' />}
          <span className='text-muted-foreground min-w-0 flex-1 truncate'>
            {owner?.name}
          </span>
          <TaskClock step={step} lane={task.lane} />
          {isSkipped && <Badge variant='secondary'>Skipped</Badge>}
        </div>
        {task.lane === 'needs' && (
          <div className='flex items-center gap-2'>
            <Badge variant='warning'>Waiting on you</Badge>
            <Button
              type='button'
              size='sm'
              variant='outline'
              onClick={onReview}
              className='ms-auto'
            >
              Review
            </Button>
          </div>
        )}
      </div>
    </motion.li>
  );
}

type BoardProps = {
  run: RunSnapshot;
  focusAgentId: string | null;
  onReview: () => void;
  className?: string;
};

export function Board({ run, focusAgentId, onReview, className }: BoardProps) {
  const groupId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const tasks = boardOf(run);
  const placement = placementOf(tasks);
  const hasFocus = focusAgentId !== null;
  const isEmpty = tasks.length === 0;

  return (
    <Panel panel='board' title='Board' className={cn('@container', className)}>
      {isEmpty && (
        <p className='text-muted-foreground py-6 text-center text-xs'>
          The plan shows here as soon as the coordinator has made it.
        </p>
      )}
      {!isEmpty && (
        <LayoutGroup id={groupId}>
          <div className='grid grid-cols-1 gap-2 @lg:grid-cols-2 @3xl:grid-cols-4'>
            {LANES.map((lane) => {
              const inLane = tasks.filter((task) => task.lane === lane.id);
              const isLaneEmpty = inLane.length === 0;
              return (
                <section
                  key={lane.id}
                  className='bg-foreground/[0.03] dark:bg-foreground/[0.05] flex min-w-0 flex-col gap-1.5 rounded-lg p-1.5'
                >
                  <h3 className='text-muted-foreground flex h-6 items-center gap-1.5 px-1.5 text-xs font-medium'>
                    {lane.label}
                    <LayoutGroup inherit={false}>
                      <MotionNumber value={inLane.length} />
                    </LayoutGroup>
                  </h3>
                  <ul className='flex flex-col gap-1.5'>
                    {inLane.map((task) => (
                      <TaskCard
                        key={task.id}
                        run={run}
                        task={task}
                        placement={placement}
                        travel={travel}
                        isDimmed={hasFocus && focusAgentId !== task.ownerId}
                        onReview={onReview}
                      />
                    ))}
                  </ul>
                  {isLaneEmpty && (
                    <p className='text-muted-foreground px-1.5 pb-1 text-xs'>
                      {lane.emptyLine}
                    </p>
                  )}
                </section>
              );
            })}
          </div>
        </LayoutGroup>
      )}
    </Panel>
  );
}

'use client';

import type { CSSProperties } from 'react';

import {
  formatCost,
  seriesColorOf,
  type RunAgent,
  type RunSnapshot,
} from '@/registry/ndeko/lib/agent-run';
import { TriangleAlertIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Fold } from '@/registry/ndeko/ui/chat-motion';

import { AgentTile, CostFigure } from './agent-parts';
import { ALERT_SHARE, BUDGET_USD } from './data';
import { Panel } from './panel';

const PERCENT = new Intl.NumberFormat('en-US', {
  style: 'percent',
  maximumFractionDigits: 0,
});

function shareOf(usd: number) {
  return Math.min(1, usd / BUDGET_USD);
}

type Slice = {
  agent: RunAgent;
  start: number;
  share: number;
};

function slicesOf(agents: RunAgent[]): Slice[] {
  const slices: Slice[] = [];
  let start = 0;
  for (const agent of agents) {
    const share = shareOf(agent.costUsd ?? 0);
    slices.push({ agent, start, share });
    start += share;
  }
  return slices;
}

function sliceStyleOf(slice: Slice): CSSProperties {
  const offset = slice.start * 100;
  return {
    backgroundColor: seriesColorOf(slice.agent.series),
    transform: `translateX(${offset}%) scaleX(${slice.share})`,
  };
}

function dimOf(isDimmed: boolean) {
  if (isDimmed) {
    return 'opacity-40';
  }
  return undefined;
}

type BudgetProps = {
  run: RunSnapshot;
  focusAgentId: string | null;
  className?: string;
};

export function Budget({ run, focusAgentId, className }: BudgetProps) {
  const total = run.usage.costUsd;
  const slices = slicesOf(run.agents);
  const share = shareOf(total);
  const isOver = share >= ALERT_SHARE;
  const left = Math.max(0, BUDGET_USD - total);
  const hasFocus = focusAgentId !== null;

  return (
    <Panel
      panel='budget'
      title='Budget'
      className={className}
      meta={<Badge variant='secondary'>Illustrative</Badge>}
    >
      <div className='flex items-baseline gap-2'>
        <CostFigure usd={total} className='text-2xl leading-8 font-semibold' />
        <span className='text-muted-foreground text-xs tabular-nums'>
          of {formatCost(BUDGET_USD)}
        </span>
      </div>
      <div className='flex flex-col gap-1.5'>
        <div
          role='img'
          aria-label={`${PERCENT.format(share)} of the budget spent`}
          className='bg-foreground/10 relative h-2 overflow-hidden rounded-full [direction:ltr]'
        >
          {slices.map((slice) => (
            <span
              key={slice.agent.id}
              style={sliceStyleOf(slice)}
              className='absolute inset-0 origin-left transition-transform duration-500 ease-(--ease-out-strong)'
            />
          ))}
          <span
            aria-hidden='true'
            style={{ left: `${ALERT_SHARE * 100}%` }}
            className='bg-foreground/40 absolute inset-y-0 w-px'
          />
        </div>
        <p className='text-muted-foreground flex justify-between text-xs tabular-nums'>
          <span>{PERCENT.format(share)} spent</span>
          <span>Alert at {PERCENT.format(ALERT_SHARE)}</span>
        </p>
      </div>
      <Fold open={isOver}>
        <p className='bg-warning/10 text-warning-foreground flex items-start gap-2 rounded-lg p-2.5 text-xs leading-5'>
          <TriangleAlertIcon className='mt-0.5 size-3.5 shrink-0' />
          Past 80% of the budget. {formatCost(left)} is left for this run.
        </p>
      </Fold>
      <ul aria-label='Spend by agent' className='flex flex-col gap-1'>
        {run.agents.map((agent) => {
          const isDimmed = hasFocus && focusAgentId !== agent.id;
          return (
            <li
              key={agent.id}
              className={cn(
                'flex h-7 items-center gap-2.5 text-[13px] transition-opacity duration-200',
                dimOf(isDimmed)
              )}
            >
              <AgentTile agent={agent} size='sm' />
              <span className='min-w-0 flex-1 truncate'>{agent.name}</span>
              <CostFigure
                usd={agent.costUsd ?? 0}
                className='text-muted-foreground text-xs'
              />
            </li>
          );
        })}
      </ul>
    </Panel>
  );
}

